const pptxgen = require("pptxgenjs");
const path = require("path");
const fs = require("fs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities";
pres.author = "Global Carbon Budget 2025 / NASA";

// Color palette - deep ocean/atmosphere theme
const C = {
  darkBg: "0A1628",       // very dark navy - title/closing slides
  midBg: "0D2240",        // dark navy - content slides
  lightBg: "EEF4FB",      // pale blue-white - light content slides
  accent1: "00C2C7",      // teal/cyan - primary accent
  accent2: "F5A623",      // amber - secondary accent / warnings
  accent3: "E84855",      // red - high emitters
  white: "FFFFFF",
  offWhite: "E8EFF8",
  muted: "8BA7C7",        // muted blue-grey
  textDark: "1A2B42",     // dark text on light bg
  textLight: "C8DCF0",    // light text on dark bg
  barColor1: "E84855",    // US/Canada - warm red
  barColor2: "F5A623",    // China - amber
  barColor3: "00C2C7",    // EU/UK - teal
  barColor4: "8BA7C7",    // World avg - muted
  barColor5: "4CAF50",    // India - green
  barColor6: "B0BEC5",    // Kenya/Chad - grey
};

const ASSET = (f) => path.resolve("/app/benchmark/assets", f);

// Helper: slide header bar for content slides
function addHeader(slide, title, bgColor, textColor) {
  slide.background = { color: bgColor };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: C.darkBg },
    line: { color: C.darkBg }
  });
  slide.addText(title, {
    x: 0.45, y: 0, w: 9.1, h: 0.72,
    fontSize: 19, bold: true, color: C.white,
    fontFace: "Calibri", align: "left", valign: "middle",
    margin: 0
  });
}

// Helper: footer
function addFooter(slide, text, textColor) {
  slide.addText(text, {
    x: 0.45, y: 5.3, w: 9.1, h: 0.28,
    fontSize: 8.5, color: C.muted, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 1 — TITLE SLIDE
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.accent1 }, line: { color: C.accent1 }
  });

  // Large atmosphere circle motif (decorative)
  slide.addShape(pres.shapes.OVAL, {
    x: 6.2, y: -1.2, w: 5.5, h: 5.5,
    fill: { color: "0D2A50", transparency: 40 },
    line: { color: C.accent1, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.0, y: -0.5, w: 3.8, h: 3.8,
    fill: { color: "0D3060", transparency: 50 },
    line: { color: C.accent1, width: 0.8 }
  });

  // Eyebrow
  slide.addText("CLIMATE DATA ANALYSIS  ·  2026", {
    x: 0.45, y: 0.75, w: 8, h: 0.35,
    fontSize: 9.5, color: C.accent1, fontFace: "Calibri",
    bold: true, charSpacing: 3, align: "left", margin: 0
  });

  // Title
  slide.addText("Global CO\u2082 Emissions", {
    x: 0.45, y: 1.18, w: 8.8, h: 0.95,
    fontSize: 44, bold: true, color: C.white,
    fontFace: "Calibri", align: "left", margin: 0
  });

  slide.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
    x: 0.45, y: 2.1, w: 8.5, h: 0.7,
    fontSize: 22, color: C.accent1,
    fontFace: "Calibri", align: "left", margin: 0
  });

  // Scope band
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 2.92, w: 4.6, h: 0.06,
    fill: { color: C.accent2 }, line: { color: C.accent2 }
  });

  slide.addText("Covering 1750 – 2024  ·  Global Carbon Budget 2025  ·  NASA / NOAA Mauna Loa", {
    x: 0.45, y: 3.08, w: 8.8, h: 0.38,
    fontSize: 11.5, color: C.muted, fontFace: "Calibri",
    align: "left", margin: 0
  });

  // Key stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 3.7, w: 4.2, h: 1.28,
    fill: { color: "0D2240" }, line: { color: C.accent1, width: 1.2 }
  });
  slide.addText("429 ppm", {
    x: 0.6, y: 3.78, w: 3.9, h: 0.6,
    fontSize: 36, bold: true, color: C.accent1, fontFace: "Calibri",
    align: "left", margin: 0
  });
  slide.addText("Atmospheric CO\u2082 · Feb 2026", {
    x: 0.6, y: 4.33, w: 3.9, h: 0.32,
    fontSize: 11, color: C.textLight, fontFace: "Calibri",
    align: "left", margin: 0
  });

  slide.addText("35+ Bt", {
    x: 5.0, y: 3.78, w: 3.5, h: 0.6,
    fontSize: 36, bold: true, color: C.accent2, fontFace: "Calibri",
    align: "left", margin: 0
  });
  slide.addText("Annual fossil fuel CO\u2082 · 2024", {
    x: 5.0, y: 4.33, w: 4.5, h: 0.32,
    fontSize: 11, color: C.textLight, fontFace: "Calibri",
    align: "left", margin: 0
  });

  // Source
  slide.addText("Source: Our World in Data — CO\u2082 and GHG Emissions (Global Carbon Budget 2025); NASA / NOAA", {
    x: 0.45, y: 5.27, w: 9.1, h: 0.28,
    fontSize: 8, color: C.muted, fontFace: "Calibri", align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 2 — ATMOSPHERIC CO2 MILESTONE
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  addHeader(slide, "Atmospheric CO₂ Reaches 429 ppm — 50% Above Pre-Industrial Levels", C.lightBg, C.textDark);

  // Big stat box left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 0.95, w: 3.6, h: 2.2,
    fill: { color: C.darkBg }, line: { color: C.accent1, width: 1.5 }
  });
  slide.addText("429", {
    x: 0.55, y: 1.0, w: 3.4, h: 1.1,
    fontSize: 72, bold: true, color: C.accent1, fontFace: "Calibri",
    align: "center", margin: 0
  });
  slide.addText("ppm CO\u2082  ·  Feb 2026", {
    x: 0.55, y: 2.0, w: 3.4, h: 0.4,
    fontSize: 13, color: C.white, fontFace: "Calibri",
    align: "center", margin: 0
  });
  slide.addText("Mauna Loa Observatory (NOAA)", {
    x: 0.55, y: 2.37, w: 3.4, h: 0.35,
    fontSize: 10, color: C.muted, fontFace: "Calibri",
    align: "center", margin: 0
  });

  // Comparison stats right col
  const stats = [
    { val: "~280 ppm", lbl: "Pre-industrial baseline (1750)", col: C.barColor5 },
    { val: "+53%", lbl: "Increase since industrialization", col: C.accent2 },
    { val: "20,000 yrs", lbl: "Natural ice-age change took this long", col: C.muted },
    { val: "~200 yrs", lbl: "Human-driven change has taken only this", col: C.accent3 },
  ];

  stats.forEach((s, i) => {
    const y = 0.95 + i * 0.82;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 4.35, y: y, w: 5.2, h: 0.72,
      fill: { color: "FFFFFF" }, line: { color: "D5E3F0", width: 0.8 }
