  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 4.38, w: 9.1, h: 0.82,
    fill: { color: C.darkBg }, line: { color: C.darkBg }
  });
  slide.addText([
    { text: "Shift in 120 years: ", options: { bold: true, color: C.white } },
    { text: "Europe + US went from >90% to <33% of global emissions. Asia rose from <10% to ~50%. Africa and South America each contribute only 3–4%.", options: { color: C.textLight } }
  ], {
    x: 0.65, y: 4.43, w: 8.7, h: 0.72,
    fontSize: 11.5, fontFace: "Calibri", align: "left", valign: "middle", margin: 0
  });

  addFooter(slide, "Source: Global Carbon Budget 2025 · Our World in Data");
}

// ─────────────────────────────────────────────
// SLIDE 6 — PER CAPITA 150x GAP
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  addHeader(slide, "Per Capita Gap: 15 t in the US vs. 0.1 t in Chad — a 150× Disparity", C.lightBg, C.textDark);

  // Horizontal bar chart
  slide.addChart(pres.charts.BAR, [
    {
      name: "Per Capita CO\u2082 (tonnes/person/year)",
      labels: ["Chad/Kenya (<1)", "India", "United Kingdom", "World Average", "EU-27", "China", "Canada", "United States"],
      values: [0.1, 2, 4, 5, 7, 9, 13, 15]
    }
  ], {
    x: 0.45, y: 0.82, w: 5.5, h: 4.3,
    barDir: "bar",
    chartColors: ["B0BEC5","4CAF50","00C2C7","8BA7C7","00C2C7","F5A623","E84855","E84855"],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: false },
    catAxisLabelColor: "1A2B42",
    valAxisLabelColor: "64748B",
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "1A2B42",
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisTitle: "Tonnes CO\u2082 per person",
    showValAxisTitle: true,
    valAxisTitleColor: "64748B",
  });

  // Reference image (figure_1 - per capita over time)
  slide.addImage({
    path: ASSET("figure_1.jpg"),
    x: 6.2, y: 0.82, w: 3.35, h: 2.45,
    sizing: { type: "contain", w: 3.35, h: 2.45 }
  });
  slide.addText("Fig. 1 — Per capita CO\u2082 over time (Our World in Data)", {
    x: 6.2, y: 3.28, w: 3.35, h: 0.28,
    fontSize: 8, color: C.muted, fontFace: "Calibri", align: "center", margin: 0
  });

  // 150x callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 3.65, w: 3.35, h: 1.0,
    fill: { color: C.darkBg }, line: { color: C.accent3, width: 1.5 }
  });
  slide.addText("150×", {
    x: 6.3, y: 3.68, w: 1.6, h: 0.55,
    fontSize: 34, bold: true, color: C.accent3, fontFace: "Calibri",
    align: "left", margin: 0
  });
  slide.addText("disparity between\nhighest and lowest\nper capita emitters", {
    x: 7.95, y: 3.68, w: 1.45, h: 0.92,
    fontSize: 9.5, color: C.textLight, fontFace: "Calibri",
    align: "left", margin: 0
  });

  addFooter(slide, "Source: Global Carbon Budget 2025 · figure_1 shows per capita trends over time");
}

// ─────────────────────────────────────────────
// SLIDE 7 — 2024 ANNUAL CHANGE MAP
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  addHeader(slide, "2024 Snapshot: US and Europe Cut Emissions While Russia and SE Asia Increase", C.lightBg, C.textDark);

  // Map image (figure_4)
  slide.addImage({
    path: ASSET("figure_4.jpg"),
    x: 0.45, y: 0.85, w: 5.8, h: 4.25,
