  });
  slide.addText("Fig. 4 — Annual % change in CO\u2082 emissions, 2024 (Our World in Data)", {
    x: 0.45, y: 5.1, w: 5.8, h: 0.22,
    fontSize: 8, color: C.muted, fontFace: "Calibri", align: "center", margin: 0
  });

  // Right panel: legend + key findings
  const findings = [
    { region: "United States", change: "\u22121% to \u22125%", dir: "down", col: "00C2C7" },
    { region: "Most of Europe", change: "\u22121% to \u22125%", dir: "down", col: "00C2C7" },
    { region: "Russia", change: "+2% to +10%", dir: "up", col: C.accent2 },
