    fontSize: 13, bold: true, color: C.textDark, fontFace: "Calibri",
    align: "left", margin: 0
  });

  findings.forEach((f, i) => {
    const y = 1.32 + i * 0.56;
    const arrowChar = f.dir === "down" ? "\u25bc" : "\u25b2";
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.45, y: y, w: 3.05, h: 0.46,
