    slide.addText(f.region + "  " + arrowChar + "  " + f.change, {
      x: 6.65, y: y + 0.04, w: 2.7, h: 0.38,
      fontSize: 11, color: C.textDark, fontFace: "Calibri",
      align: "left", margin: 0
    });
