  // Bottom note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.45, y: 4.68, w: 3.05, h: 0.58,
    fill: { color: C.darkBg }, line: { color: C.darkBg }
  });
  slide.addText("Blue = decline  ·  Orange/Red = increase", {
    x: 6.6, y: 4.74, w: 2.8, h: 0.46,
    fontSize: 10, color: C.textLight, fontFace: "Calibri",
    align: "left", margin: 0
  });

  addFooter(slide, "Source: Global Carbon Budget 2025 · figure_4 shows 2024 annual % change map");
}

// ─────────────────────────────────────────────
// SLIDE 8 — ENERGY MIX DRIVES DIFFERENCES
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  addHeader(slide, "Energy Mix Explains Why France Emits Far Less Per Capita Than Germany", C.lightBg, C.textDark);

  // Intro text
  slide.addText("Countries with similar living standards can have very different per capita CO\u2082 emissions — the key variable is their energy source mix.", {
    x: 0.45, y: 0.85, w: 9.1, h: 0.52,
    fontSize: 12.5, color: C.textDark, fontFace: "Calibri",
    align: "left", margin: 0
  });

  // Comparison table
  const tableData = [
    [
      { text: "Country", options: { bold: true, color: "FFFFFF", fill: { color: C.darkBg }, fontSize: 12 } },
      { text: "Per Capita CO₂", options: { bold: true, color: "FFFFFF", fill: { color: C.darkBg }, fontSize: 12 } },
      { text: "Nuclear Share", options: { bold: true, color: "FFFFFF", fill: { color: C.darkBg }, fontSize: 12 } },
      { text: "Renewables Share", options: { bold: true, color: "FFFFFF", fill: { color: C.darkBg }, fontSize: 12 } },
