      { text: "~4 t/person", options: { bold: true, color: "2E7D32", fill: { color: "E8F5E9" }, fontSize: 11 } },
      { text: "High (~70%)", options: { color: "2E7D32", fill: { color: "E8F5E9" }, fontSize: 11 } },
      { text: "Growing", options: { color: C.textDark, fill: { color: "E8F5E9" }, fontSize: 11 } },
      { text: "Low", options: { bold: true, color: "2E7D32", fill: { color: "E8F5E9" }, fontSize: 11 } },
