      { text: "High (wind)", options: { color: "2E7D32", fill: { color: "E8F5E9" }, fontSize: 11 } },
      { text: "Declining", options: { bold: true, color: "2E7D32", fill: { color: "E8F5E9" }, fontSize: 11 } },
    ],
    [
      { text: "🇩🇪 Germany", options: { bold: true, color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "~7–8 t/person*", options: { bold: true, color: "E65100", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Low (phase-out)", options: { color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Growing", options: { color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Still high", options: { bold: true, color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
    ],
    [
      { text: "🇳🇱 Netherlands", options: { bold: true, color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
