      { text: "None", options: { color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Growing", options: { color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "High (gas-heavy)", options: { bold: true, color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
    ],
  ];

  slide.addTable(tableData, {
    x: 0.45, y: 1.48, w: 9.1, h: 2.35,
