    colW: [1.9, 1.65, 1.65, 1.65, 2.25],
  });

  // Green = low-carbon label
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 3.98, w: 4.3, h: 0.32,
    fill: { color: "E8F5E9" }, line: { color: "A5D6A7", width: 0.8 }
  });
  slide.addText("Green shading = lower per capita CO\u2082 / low fossil reliance", {
    x: 0.55, y: 3.98, w: 4.1, h: 0.32,
    fontSize: 9.5, color: "2E7D32", fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });
  slide.addShape(pres.shapes.RECTANGLE, {
