  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 4.45, w: 9.1, h: 0.72,
    fill: { color: C.darkBg }, line: { color: C.darkBg }
  });
  slide.addText([
    { text: "Key insight: ", options: { bold: true, color: C.accent1 } },
    { text: "France and Germany have comparable living standards, yet France emits roughly ", options: { color: C.textLight } },
    { text: "half as much CO\u2082 per person", options: { bold: true, color: C.accent1 } },
    { text: " — a direct result of energy policy choices, not prosperity. Policy and energy mix, not wealth alone, determine per capita outcomes.", options: { color: C.textLight } }
  ], {
    x: 0.65, y: 4.48, w: 8.7, h: 0.65,
    fontSize: 11.5, fontFace: "Calibri", align: "left", valign: "middle", margin: 0
  });

  addFooter(slide, "* Germany ~0.6 Bt total / ~72M pop ≈ ~8t; Netherlands ~0.15 Bt / ~18M pop ≈ ~8t  ·  Source: Global Carbon Budget 2025");
