  // Header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: "06101F" }, line: { color: "06101F" }
  });
  slide.addText("Key Takeaways: Emissions Are Still Rising, But the Map of Responsibility Is Shifting", {
    x: 0.45, y: 0, w: 9.1, h: 0.72,
    fontSize: 17, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });

  // 5 takeaway cards
  const takeaways = [
    {
      num: "01",
      head: "Global emissions exceed 35 Bt — not yet peaked",
      body: "Fossil fuel CO\u2082 now surpasses 35 billion tonnes/year. Growth has slowed but annual emissions continue to rise.",
      col: C.accent3,
    },
    {
      num: "02",
      head: "China alone emits >25% of the global total",
      body: "At ~12.5 Bt, China is more than double the US (~5 Bt). India (~3 Bt) is the third largest and rising fast.",
      col: C.accent2,
    },
    {
      num: "03",
      head: "Geographic center of emissions has shifted east",
      body: "Europe + US: from >90% in 1900 to <33% today. Asia now accounts for ~50% of global emissions.",
      col: C.accent1,
    },
    {
      num: "04",
      head: "Per capita inequalities remain extreme: 150\u00d7 gap",
      body: "The US and Australia (~15 t/person) vs. Chad or Niger (~0.1 t/person). Those who emit least face the greatest climate risks.",
      col: "F5A623",
    },
    {
      num: "05",
      head: "Energy mix — not prosperity — drives per capita outcomes",
      body: "France vs. Germany illustrates how policy choices on nuclear and renewables create vastly different emission profiles at comparable living standards.",
      col: "4CAF50",
    },
  ];

  // Two-column layout: 3 left, 2 right
  const cardW = 4.5, cardH = 1.08;
  const positions = [
    { x: 0.45, y: 0.85 },
    { x: 0.45, y: 2.02 },
    { x: 0.45, y: 3.19 },
    { x: 5.1, y: 0.85 },
    { x: 5.1, y: 2.02 },
  ];

  takeaways.forEach((t, i) => {
    const pos = positions[i];
    slide.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: cardW, h: cardH,
      fill: { color: "0D2240" }, line: { color: t.col, width: 1.2 }
    });
    // Accent left bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: 0.1, h: cardH,
      fill: { color: t.col }, line: { color: t.col }
