  slide.addText([
    { text: "Data Sources\n", options: { bold: true, color: C.accent1, breakLine: false } },
    { text: "Global Carbon Budget 2025\n", options: { color: C.textLight, breakLine: false } },
    { text: "NASA / NOAA Mauna Loa Observatory\n", options: { color: C.textLight, breakLine: false } },
    { text: "Our World in Data — CO\u2082 & GHG Emissions", options: { color: C.textLight } },
  ], {
    x: 5.3, y: 3.24, w: 4.1, h: 0.98,
    fontSize: 10.5, fontFace: "Calibri", align: "left", valign: "top", margin: 0
  });

  // Bottom source line
  slide.addText("Global CO\u2082 Emissions: Trends, Regional Shifts, and Per Capita Inequalities  ·  2026", {
    x: 0.45, y: 5.3, w: 9.1, h: 0.28,
    fontSize: 8.5, color: "2A4A6A", fontFace: "Calibri",
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// WRITE FILE
// ─────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅ Saved: /app/output/final_deck.pptx"))
  .catch((e) => { console.error("❌ Error:", e); process.exit(1); });

