      { text: "🇩🇪 Germany", options: { bold: true, color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "~7–8 t/person*", options: { bold: true, color: "E65100", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Low (phase-out)", options: { color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Growing", options: { color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Still high", options: { bold: true, color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
    ],
    [
      { text: "🇳🇱 Netherlands", options: { bold: true, color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "~8 t/person*", options: { bold: true, color: "E65100", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "None", options: { color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "Growing", options: { color: C.textDark, fill: { color: "FFF8E1" }, fontSize: 11 } },
      { text: "High (gas-heavy)", options: { bold: true, color: "C62828", fill: { color: "FFF8E1" }, fontSize: 11 } },
    ],
  ];

  slide.addTable(tableData, {
    x: 0.45, y: 1.48, w: 9.1, h: 2.35,
    border: { pt: 0.8, color: "D5E3F0" },
    rowH: 0.47,
    colW: [1.9, 1.65, 1.65, 1.65, 2.25],
  });

  // Green = low-carbon label
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 3.98, w: 4.3, h: 0.32,
    fill: { color: "E8F5E9" }, line: { color: "A5D6A7", width: 0.8 }
  });
  slide.addText("Green shading = lower per capita CO\u2082 / low fossil reliance", {
    x: 0.55, y: 3.98, w: 4.1, h: 0.32,
    fontSize: 9.5, color: "2E7D32", fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.9, y: 3.98, w: 4.65, h: 0.32,
    fill: { color: "FFF8E1" }, line: { color: "FFE082", width: 0.8 }
  });
  slide.addText("Amber shading = higher per capita CO\u2082 / fossil-heavy mix", {
    x: 5.0, y: 3.98, w: 4.45, h: 0.32,
    fontSize: 9.5, color: "E65100", fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 4.45, w: 9.1, h: 0.72,
    fill: { color: C.darkBg }, line: { color: C.darkBg }
  });
  slide.addText([
    { text: "Key insight: ", options: { bold: true, color: C.accent1 } },
    { text: "France and Germany have comparable living standards, yet France emits roughly ", options: { color: C.textLight } },
    { text: "half as much CO\u2082 per person", options: { bold: true, color: C.accent1 } },
    { text: " — a direct result of energy policy choices, not prosperity. Policy and energy mix, not wealth alone, determine per capita outcomes.", options: { color: C.textLight } }
  ], {
    x: 0.65, y: 4.48, w: 8.7, h: 0.65,
    fontSize: 11.5, fontFace: "Calibri", align: "left", valign: "middle", margin: 0
  });

  addFooter(slide, "* Germany ~0.6 Bt total / ~72M pop ≈ ~8t; Netherlands ~0.15 Bt / ~18M pop ≈ ~8t  ·  Source: Global Carbon Budget 2025");
}

// ─────────────────────────────────────────────
// SLIDE 9 — KEY TAKEAWAYS
// ─────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: "06101F" }, line: { color: "06101F" }
  });
  slide.addText("Key Takeaways: Emissions Are Still Rising, But the Map of Responsibility Is Shifting", {
    x: 0.45, y: 0, w: 9.1, h: 0.72,
    fontSize: 17, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });

  // 5 takeaway cards
  const takeaways = [
    {
      num: "01",
      head: "Global emissions exceed 35 Bt — not yet peaked",
      body: "Fossil fuel CO\u2082 now surpasses 35 billion tonnes/year. Growth has slowed but annual emissions continue to rise.",
      col: C.accent3,
    },
    {
      num: "02",
      head: "China alone emits >25% of the global total",
      body: "At ~12.5 Bt, China is more than double the US (~5 Bt). India (~3 Bt) is the third largest and rising fast.",
      col: C.accent2,
    },
    {
      num: "03",
      head: "Geographic center of emissions has shifted east",
      body: "Europe + US: from >90% in 1900 to <33% today. Asia now accounts for ~50% of global emissions.",
      col: C.accent1,
    },
    {
      num: "04",
      head: "Per capita inequalities remain extreme: 150\u00d7 gap",
      body: "The US and Australia (~15 t/person) vs. Chad or Niger (~0.1 t/person). Those who emit least face the greatest climate risks.",
      col: "F5A623",
    },
    {
      num: "05",
      head: "Energy mix — not prosperity — drives per capita outcomes",
      body: "France vs. Germany illustrates how policy choices on nuclear and renewables create vastly different emission profiles at comparable living standards.",
      col: "4CAF50",
    },
  ];

  // Two-column layout: 3 left, 2 right
  const cardW = 4.5, cardH = 1.08;
  const positions = [
    { x: 0.45, y: 0.85 },
    { x: 0.45, y: 2.02 },
    { x: 0.45, y: 3.19 },
    { x: 5.1, y: 0.85 },
    { x: 5.1, y: 2.02 },
  ];

  takeaways.forEach((t, i) => {
    const pos = positions[i];
    slide.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: cardW, h: cardH,
      fill: { color: "0D2240" }, line: { color: t.col, width: 1.2 }
    });
    // Accent left bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: 0.1, h: cardH,
      fill: { color: t.col }, line: { color: t.col }
    });
    // Number
    slide.addText(t.num, {
      x: pos.x + 0.2, y: pos.y + 0.04, w: 0.55, h: 0.4,
      fontSize: 18, bold: true, color: t.col, fontFace: "Calibri",
      align: "left", margin: 0
    });
    // Headline
    slide.addText(t.head, {
      x: pos.x + 0.75, y: pos.y + 0.04, w: cardW - 0.9, h: 0.4,
      fontSize: 11.5, bold: true, color: C.white, fontFace: "Calibri",
      align: "left", margin: 0
    });
    // Body
    slide.addText(t.body, {
      x: pos.x + 0.2, y: pos.y + 0.47, w: cardW - 0.35, h: 0.56,
      fontSize: 10, color: C.textLight, fontFace: "Calibri",
      align: "left", margin: 0
    });
  });

  // 6th slot: source attribution
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 3.19, w: cardW, h: cardH,
    fill: { color: "06101F" }, line: { color: "1A3A60", width: 1 }
  });
  slide.addText([
    { text: "Data Sources\n", options: { bold: true, color: C.accent1, breakLine: false } },
    { text: "Global Carbon Budget 2025\n", options: { color: C.textLight, breakLine: false } },
    { text: "NASA / NOAA Mauna Loa Observatory\n", options: { color: C.textLight, breakLine: false } },
    { text: "Our World in Data — CO\u2082 & GHG Emissions", options: { color: C.textLight } },
  ], {
    x: 5.3, y: 3.24, w: 4.1, h: 0.98,
    fontSize: 10.5, fontFace: "Calibri", align: "left", valign: "top", margin: 0
  });

  // Bottom source line
  slide.addText("Global CO\u2082 Emissions: Trends, Regional Shifts, and Per Capita Inequalities  ·  2026", {
    x: 0.45, y: 5.3, w: 9.1, h: 0.28,
    fontSize: 8.5, color: "2A4A6A", fontFace: "Calibri",
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// WRITE FILE
// ─────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅ Saved: /app/output/final_deck.pptx"))
  .catch((e) => { console.error("❌ Error:", e); process.exit(1); });

